/**
 * Passage 1: tone the canvas and block in the big masses.
 *
 * A warm wash goes over the grey ground first, then every mass of the picture (sky,
 * headland, sea, wet sand, dry sand, the dark accents) is laid in thin, lean paint
 * with big brushes. Nothing here is final; it fixes where the lights and darks sit,
 * and the warm ground keeps glowing through the gaps of every later passage.
 */

// The tubes on the palette. Every other color in the painting is mixed from these.
palette('white', '#f5f2ea');
palette('cadYellow', '#f6c40f');
palette('ochre', '#c48a2c');
palette('cadRed', '#cf3a1e');
palette('alizarin', '#7d1b2e');
palette('ultra', '#24308e');
palette('sienna', '#8b4522');

// Piles mixed once and reused by later passages. The sky runs from the glow around the
// sun to the cool high sky, a string of tones laid out across the palette.
palette('skyGlow', mix(['white', 8], ['cadYellow', 1.4]));
palette('skyGold', mix(['white', 6], ['cadYellow', 1], ['ochre', 0.6], ['cadRed', 0.12]));
palette('skyPeach', mix(['white', 5], ['ochre', 0.8], ['cadRed', 0.35]));
palette('skyRose', mix(['white', 5], ['alizarin', 0.5], ['ochre', 0.4], ['ultra', 0.08]));
palette('skyLilac', mix(['white', 4.5], ['ultra', 0.55], ['alizarin', 0.45]));
palette('skyBlue', mix(['white', 4], ['ultra', 1], ['alizarin', 0.3]));
palette('skyHigh', mix(['white', 2.6], ['ultra', 1], ['alizarin', 0.35], ['sienna', 0.12]));
palette('cloud', mix(['white', 3], ['ultra', 0.8], ['alizarin', 0.6], ['ochre', 0.4]));
palette('headland', mix(['white', 2], ['ultra', 1], ['alizarin', 0.6], ['ochre', 0.2]));
palette('sea', mix(['ultra', 2], ['alizarin', 1.4], ['sienna', 0.4], ['white', 0.9]));
palette('sandWet', mix(['white', 2], ['alizarin', 0.5], ['ultra', 0.5], ['sienna', 0.3]));
palette('sandDry', mix(['ochre', 2], ['white', 3], ['sienna', 0.5], ['alizarin', 0.2]));
palette('shade', mix(['sienna', 1], ['white', 1.5], ['alizarin', 0.4], ['ultra', 0.7]));
palette('darkest', mix(['ultra', 1], ['alizarin', 0.8], ['sienna', 0.6]));

const W = canvas.width;
const H = canvas.height;
const HORIZON = 332; // the sea line
const SHORE = 372; // where the sea breaks onto wet sand
const SUN = { x: 432, y: 248 };

const SKY = ['skyGlow', 'skyGold', 'skyPeach', 'skyRose', 'skyLilac', 'skyBlue', 'skyHigh'];

/**
 * Which pile of the sky string goes where: rings around the sun, wider than tall and
 * pulled warmer low down by the sea, glow inside the first ring and high sky past the
 * last. Each ring's edge is left ragged, so neighboring piles meet in broken color.
 */
const RINGS = [47, 140, 233, 327, 420, 513];
function skyPile(x, y) {
  const d =
    Math.hypot((x - SUN.x) / 1.35, (y - SUN.y) * 1.1) - Math.max(0, y - 190) * 1.1 + rand(-30, 30);
  const i = RINGS.findIndex((r) => d < r);
  return SKY[i < 0 ? SKY.length - 1 : i];
}

/** Where the wet sand gives way to dry: a wandering line, lower on the left where a channel runs. */
function dryLine(x) {
  return 615 + 38 * noise(x / 170, 7.3) + Math.max(0, 300 - x) * 0.18;
}

/** The headland's ridge on the right, rising out of the sea. */
function headTop(x) {
  if (x < 730) return HORIZON;
  const rise = Math.min(1, (x - 730) / 240) ** 0.75 * 44 + Math.max(0, x - 980) * 0.04;
  return HORIZON - rise + noise(x / 55, 2.6) * 4;
}

/** A loose horizontal stroke from (x, y), length len, with a little sag and tilt. */
function sweep(x, y, len, tilt = 0) {
  return [
    [x, y],
    [x + len * 0.5, y + rand(-3, 3) + tilt * 0.5],
    [x + len, y + rand(-4, 4) + tilt],
  ];
}

brush('wash', { type: 'flat', width: 130, reservoir: 5, streak: 0.7 });
brush('block', { type: 'filbert', width: 64, reservoir: 2 });
brush('blockSmall', { type: 'filbert', width: 26 });

// The imprimatura: a thin warm wash over the whole canvas, crossing at two angles.
const wash = mix(['ochre', 1.4], ['cadRed', 0.4], ['white', 2.5], ['sienna', 0.5]);
for (let pass = 0; pass < 2; pass++) {
  const tilt = pass === 0 ? 0.36 : -0.3;
  // strokes running downhill start above the canvas, uphill ones below it
  for (let y = pass === 0 ? -170 : 40; y < (pass === 0 ? H - 40 : H + 170); y += 95) {
    for (let x = -120; x < W - 60; x += rand(330, 430)) {
      const len = rand(380, 520);
      const end = [x + len, y + len * tilt + rand(-20, 20)];
      if (end[0] > W + 200 && y < 0) continue; // would only graze the corner
      stroke({
        path: [[x, y + rand(-20, 20)], end],
        brush: 'wash',
        color: wash,
        paint: 'semi_opaque',
        thinner: 0.7,
        load: rand(0.45, 0.7),
      });
    }
  }
}
// The wash sets before the masses go over it, so they keep their own color.
dry();

// Sky: rows of broad, lean strokes, each taking the pile of its ring around the sun.
for (let y = 10; y < HORIZON - 4; y += 34) {
  for (let x = -40; x < W; x += rand(120, 190)) {
    const len = rand(170, 260);
    stroke({
      path: sweep(x, y + rand(-6, 6), len, rand(-10, 10)),
      brush: 'block',
      color: skyPile(x + len / 2, y),
      thinner: 0.4,
      load: 0.6,
    });
  }
}

// The headland: strokes that follow its ridge, then fill down to the sea line. Fuller
// paint than the sky, since it goes into the sky's wet edge.
for (let row = 0; row < 4; row++) {
  for (let x = 720 + row * 30; x < W; x += rand(90, 130)) {
    const pts = [];
    for (let k = 0; k <= 4; k++) {
      const px = x + k * 34;
      const top = headTop(px);
      pts.push([px, top + 9 + row * ((HORIZON - top) / 4)]);
    }
    stroke({ path: pts, brush: 'blockSmall', color: 'headland', thinner: 0.1, load: 0.9 });
  }
}

// Sea: a dark band, warmer and lighter where the sun's path crosses it.
for (let y = HORIZON + 4; y < SHORE + 4; y += 16) {
  for (let x = -30; x < W; x += rand(110, 160)) {
    const len = rand(130, 200);
    const near = Math.abs(x + len / 2 - SUN.x) < 110;
    stroke({
      path: sweep(x, y, len, rand(-2, 2)),
      brush: { type: 'flat', width: 28 },
      color: near ? mix(['sea', 1], ['skyGold', 1.4]) : 'sea',
      thinner: 0.35,
    });
  }
}

// Wet sand: it mirrors the sky, darker and warmer, with the sun's path running down it.
for (let y = SHORE; y < H; y += 30) {
  for (let x = -40; x < W; x += rand(140, 200)) {
    const len = rand(170, 240);
    const cx = x + len / 2;
    if (y > dryLine(cx) + 20) continue;
    const inSunPath = Math.abs(cx - SUN.x) < 50 + (y - HORIZON) * 0.4;
    stroke({
      path: sweep(x, y + rand(-5, 5), len, rand(-6, 6)),
      brush: 'block',
      color: inSunPath
        ? mix(['sandWet', 1], ['skyGold', 2.5])
        : mix(['sandWet', 3], ['skyRose', 1]),
      thinner: 0.4,
      load: 0.6,
    });
  }
}

// Dry sand: warm, darkening toward the bottom edge, where the foreground falls into
// shade. Three piles, stepped down in value, laid in bands with ragged edges.
const SAND_BLOCK = [
  mix(['sandDry', 2.6], ['shade', 0.9], ['darkest', 0.12]),
  mix(['sandDry', 2], ['shade', 1.75], ['darkest', 0.3]),
  mix(['sandDry', 1.3], ['shade', 2.6], ['darkest', 0.48]),
];
for (let y = 560; y < H + 30; y += 32) {
  for (let x = -40; x < W; x += rand(140, 200)) {
    const len = rand(170, 240);
    const cx = x + len / 2;
    if (y < dryLine(cx) - 10) continue;
    const band = Math.min(2, Math.max(0, Math.floor((y - 620) / 90 + rand(-0.4, 0.4))));
    stroke({
      path: sweep(x, y + rand(-5, 5), len, rand(-8, 8)),
      brush: 'block',
      color: SAND_BLOCK[band],
      thinner: 0.25,
      load: 0.7,
    });
  }
}

// The darks, drawn in thin paint: the big boat, the far boat, and the line of old posts.
const thinDark = { color: 'darkest', thinner: 0.45, load: 0.7 };
for (let i = 0; i < 4; i++) {
  const y = 528 + i * 11;
  stroke({
    path: [
      [648 + i * 9, y],
      [760, y + 6 - i * 2],
      [858 - i * 14, y - 18 + i * 4],
    ],
    brush: { type: 'flat', width: 14 },
    ...thinDark,
  });
}
stroke({
  path: [
    [948, 431],
    [985, 434],
    [1022, 426],
  ],
  brush: { type: 'flat', width: 9 },
  ...thinDark,
});
for (let i = 0; i < 7; i++) {
  const t = i / 6;
  const x = 150 + t * 175;
  const foot = 870 - (870 - 398) * t ** 0.8;
  const tall = 120 * (1 - t) ** 1.4 + 10;
  stroke({
    path: [
      [x, foot],
      [x + 1, foot - tall],
    ],
    brush: { type: 'flat', width: 15 * (1 - t) + 3 },
    ...thinDark,
  });
}

// Lean paint dries before the body color goes on.
dry();

/**
 * Passage 2: the sky, in body color, wet into wet.
 *
 * Short crossing strokes take their tone from the string of sky mixes laid out in the
 * first passage, with a stroke of a neighboring hue dropped in here and there: broken
 * color, so the sky vibrates instead of grading smoothly. Stiff bristles and a full
 * load keep each stroke its own color. Bars of cloud go in over the wet sky, each a
 * row of soft puffs whose edges toward the sun catch the light, and a clean soft brush
 * melts their far edges before the sky is left to dry.
 */

const W = canvas.width;
const HORIZON = 332;
const SUN = { x: 432, y: 248 };
const SKY = ['skyGlow', 'skyGold', 'skyPeach', 'skyRose', 'skyLilac', 'skyBlue', 'skyHigh'];

/**
 * Which pile of the sky string a point takes (as in passage 1): rings around the sun,
 * wider than tall and warmer low down, glow inside the first and high sky past the
 * last, each ring's edge left ragged.
 */
const RINGS = [47, 140, 233, 327, 420, 513];
function skyIndex(x, y) {
  const d =
    Math.hypot((x - SUN.x) / 1.35, (y - SUN.y) * 1.1) - Math.max(0, y - 190) * 1.1 + rand(-25, 25);
  const i = RINGS.findIndex((r) => d < r);
  return i < 0 ? SKY.length - 1 : i;
}
const pile = (i) => SKY[Math.min(SKY.length - 1, Math.max(0, i))];

/** The headland's ridge (as in passage 1): the sky stops at it. */
function headTop(x) {
  if (x < 730) return HORIZON;
  const rise = Math.min(1, (x - 730) / 240) ** 0.75 * 44 + Math.max(0, x - 980) * 0.04;
  return HORIZON - rise + noise(x / 55, 2.6) * 4;
}

/** The lowest the sky's paint may reach at x. */
const skyFloor = (x) => headTop(x) - 3;

brush('skyBristle', { type: 'filbert', width: 30, splay: 0.3, stiffness: 0.85 });
brush('skySmall', { type: 'filbert', width: 16, splay: 0.3, stiffness: 0.85 });
brush('rigger', { type: 'round', width: 7 });
brush('blender', { type: 'soft', width: 34 });

// The sky field: short strokes, laid level near the sea and crossing more higher up.
for (let y = 6; y < HORIZON - 4; y += 14) {
  for (let x = -20; x < W + 20; x += rand(38, 62)) {
    if (y > skyFloor(x) - 4) continue;
    const i = skyIndex(x, y);
    const len = rand(45, 95);
    const swing = Math.max(0, 1 - y / (HORIZON - 60)) * 0.55;
    // a drift from the noise field, plus a random cross one way or the other
    const a = noise(x / 160, y / 90) * swing + (rand() < 0.5 ? swing : -swing) * rand(0.3, 1);
    const dx = (Math.cos(a) * len) / 2;
    const dy = (Math.sin(a) * len) / 2;
    // one stroke in five is a neighboring hue: a rose in the gold, a gold in the lilac
    const color = rand() < 0.2 ? pile(i + (rand() < 0.5 ? -1 : 1)) : pile(i);
    stroke({
      path: [
        [x - dx, Math.min(y - dy, skyFloor(x - dx))],
        [x + dx, Math.min(y + dy + rand(-3, 3), skyFloor(x + dx))],
      ],
      brush: i <= 1 ? 'skySmall' : 'skyBristle',
      color,
      load: rand(0.75, 0.95),
      pressure: rand(0.5, 0.85),
    });
  }
}

/**
 * The bars of cloud: where each runs and how thick it gets. A bar is a row of puffs,
 * round on top and flattened underneath, thickest in the middle of the bar.
 */
const CLOUDS = [
  { x0: -40, x1: 420, y: 70, slope: 0.05, thick: 34 },
  { x0: 650, x1: 1240, y: 92, slope: -0.05, thick: 30 },
  { x0: 150, x1: 930, y: 186, slope: 0.035, thick: 24 },
  { x0: 488, x1: 720, y: 262, slope: -0.02, thick: 11 },
  { x0: 770, x1: 1240, y: 266, slope: -0.03, thick: 20 },
  { x0: -40, x1: 300, y: 298, slope: 0.02, thick: 13 },
];

for (const c of CLOUDS) {
  const span = c.x1 - c.x0;
  const sunBelow = SUN.y > c.y;
  const puffs = [];
  for (let x = c.x0 + rand(10, 30); x < c.x1; x += rand(40, 70)) {
    const u = (x - c.x0) / span;
    const env = Math.sin(Math.PI * Math.min(1, Math.max(0, u))) ** 0.7;
    puffs.push({
      x,
      y: c.y + (x - (c.x0 + c.x1) / 2) * c.slope + rand(-3, 3),
      rx: rand(38, 70),
      ry: Math.max(4, c.thick * env * rand(0.55, 1.05)),
    });
  }

  for (const p of puffs) {
    // the body: rose-violet against the glow, lilac out in the cool sky
    const i = skyIndex(p.x, p.y);
    const body =
      i <= 2
        ? mix(['cloud', 1.5], ['skyRose', 1], ['alizarin', 0.06])
        : mix(['cloud', 1.1], ['skyLilac', 1], [pile(i), 0.6]);
    const top = p.y - p.ry;
    const bottom = p.y + p.ry * 0.45;
    for (let y = top + 3; y < bottom; y += 7) {
      const v = y < p.y ? (p.y - y) / p.ry : (y - p.y) / (p.ry * 0.45);
      const half = p.rx * Math.sqrt(Math.max(0, 1 - v * v));
      if (half < 6) continue;
      stroke({
        path: [
          [p.x - half, y + rand(-1.5, 1.5)],
          [p.x + half, y + 2 * half * c.slope + rand(-1.5, 1.5)],
        ],
        brush: p.ry > 9 ? 'skySmall' : 'rigger',
        color: body,
        load: 0.85,
        pressure: rand(0.55, 0.8),
      });
    }

    // the side toward the sun catches the light, brightest nearest it
    const light = 1 - Math.hypot(p.x - SUN.x, (p.y - SUN.y) * 1.6) / 560;
    if (light > 0.05) {
      const rim =
        light > 0.5
          ? mix(['skyGlow', 3], ['white', 1])
          : light > 0.25
            ? mix(['skyGold', 1.2], ['skyPeach', 1])
            : mix(['skyGold', 0.5], ['skyPeach', 1]);
      if (sunBelow) {
        // a long line of light under the base, and a shorter, brighter one inside it
        for (const [k, y] of [
          [1.4, bottom],
          [0.7, bottom - 2],
        ]) {
          const len = p.rx * k * rand(0.8, 1.2);
          stroke({
            path: [
              [p.x - len / 2, y],
              [p.x, y + rand(-1, 1)],
              [p.x + len / 2, y + len * c.slope],
            ],
            brush: 'rigger',
            color: k < 1 ? mix([rim, 2], ['white', 1]) : rim,
            load: 1,
            pressure: 0.5 + light * 0.45,
            end: 'taper',
          });
        }
      } else {
        // an arc over the puff's crown
        const arc = [];
        for (let a = Math.PI + 0.35; a <= 2 * Math.PI - 0.35; a += 0.3)
          arc.push([p.x + Math.cos(a) * p.rx * 0.9, p.y + Math.sin(a) * p.ry * 0.95]);
        stroke({
          path: arc,
          brush: 'rigger',
          color: rim,
          load: 0.9,
          pressure: 0.45 + light * 0.4,
          end: 'taper',
        });
      }
    }
  }

  // a clean soft brush drawn along the far side melts it into the sky
  for (const p of puffs) {
    if (p.x > W - 20) continue;
    const y = sunBelow ? p.y - p.ry : p.y + p.ry * 0.45;
    stroke({
      path: [
        [p.x - p.rx * 0.7, y],
        [p.x + p.rx * 0.7, y + p.rx * 1.4 * c.slope],
      ],
      brush: 'blender',
      pressure: 0.4,
    });
  }
}

// The sun's halo: short strokes of the palest mix around the place the sun will sit.
for (let i = 0; i < 44; i++) {
  const a = rand(Math.PI * 2);
  const r = rand(12, 60);
  const x = SUN.x + Math.cos(a) * r * 1.3;
  const y = SUN.y + Math.sin(a) * r;
  stroke({
    path: [
      [x - rand(8, 16), y],
      [x + rand(8, 16), y + rand(-4, 4)],
    ],
    brush: 'skySmall',
    color: r < 32 ? mix(['white', 2], ['skyGlow', 1]) : 'skyGlow',
    load: 0.9,
  });
}

// The sky sets before the sea and headland are painted against it.
dry({ x: 0, y: 0, w: W, h: HORIZON + 2 });

/**
 * Passage 3: the headland and the strip of sea.
 *
 * Against the sun the headland is one flat, cool shape, warmed only where its slope
 * catches the light; it is painted in strokes that follow the ridge. The sea is a
 * dark band in short level strokes, paler toward the horizon, broken under the sun by
 * a path of glitter that widens as it comes toward us. A broken line of surf marks
 * where the sea runs out onto the sand.
 */

const W = canvas.width;
const HORIZON = 332;
const SHORE = 372;
const SUN = { x: 432, y: 248 };

function headTop(x) {
  if (x < 730) return HORIZON;
  const rise = Math.min(1, (x - 730) / 240) ** 0.75 * 44 + Math.max(0, x - 980) * 0.04;
  return HORIZON - rise + noise(x / 55, 2.6) * 4;
}

/** Half-width of the sun's path on the water at height y: narrow at the horizon, wider nearer. */
const pathHalf = (y) => 26 + (y - HORIZON) * 0.9;

brush('ridge', { type: 'filbert', width: 12, stiffness: 0.8 });
brush('water', { type: 'filbert', width: 10, stiffness: 0.8 });
brush('glint', { type: 'flat', width: 3, stiffness: 0.9 });

// Headland: ridge strokes first, then level strokes filling down to the water, darkest at the foot.
const headFar = mix(['headland', 2], ['skyLilac', 1]);
const headNear = mix(['headland', 2], ['sea', 0.6]);
// three piles for the slope, from the ridge down to the foot
const HEAD = [
  mix(['headland', 1.75], [headNear, 0.55]),
  mix(['headland', 1.5], [headNear, 1.05]),
  mix(['headland', 1.15], [headNear, 1.6]),
];
for (let x = 724; x < W; x += rand(26, 40)) {
  const len = rand(36, 60);
  stroke({
    path: [
      [x, headTop(x) + 3],
      [x + len / 2, headTop(x + len / 2) + 3],
      [x + len, headTop(x + len) + 3],
    ],
    brush: 'ridge',
    color: rand() < 0.3 ? headFar : 'headland',
    load: 0.85,
  });
}
for (let y = HORIZON - 44; y < HORIZON + 1; y += 6) {
  for (let x = 720; x < W; x += rand(40, 70)) {
    if (y < headTop(x) + 7) continue;
    const depth = (y - headTop(x)) / (HORIZON - headTop(x) + 1);
    const band = Math.min(2, Math.max(0, Math.floor(depth * 3 + rand(-0.4, 0.4))));
    stroke({
      path: [
        [x, y],
        [x + rand(45, 80), y + rand(-1.5, 1.5)],
      ],
      brush: 'ridge',
      color: HEAD[band],
      load: 0.8,
      pressure: 0.6,
    });
  }
}
// the left slope, turned toward the sun, takes a little warm light along its crest
for (let x = 734; x < 900; x += rand(16, 26)) {
  stroke({
    path: [
      [x, headTop(x) + 1.5],
      [x + 18, headTop(x + 18) + 1.5],
    ],
    brush: { type: 'round', width: 4 },
    color: mix(['skyPeach', 2], ['skyRose', 1]),
    load: 0.8,
    pressure: 0.5,
    end: 'taper',
  });
}

// Sea: long level strokes, paler and greyer at the horizon, deep violet toward the
// shore, each tipped a degree or two the way the swell lifts it. Three piles stepped
// from the horizon to the shore, each with a rose variant for broken color.
const SEA = [
  { lilac: mix(['sea', 1.2], ['skyLilac', 1]), rose: mix(['sea', 1.2], ['skyRose', 1]) },
  { lilac: mix(['sea', 1.7], ['skyLilac', 0.8]), rose: mix(['sea', 1.7], ['skyRose', 0.8]) },
  { lilac: mix(['sea', 2.2], ['skyLilac', 0.6]), rose: mix(['sea', 2.2], ['skyRose', 0.6]) },
];
for (let y = HORIZON + 3; y < SHORE + 1; y += 5) {
  const depth = (y - HORIZON) / (SHORE - HORIZON);
  for (let x = -10; x < W; x += rand(50, 100)) {
    const len = rand(60, 160);
    const cx = x + len / 2;
    const inPath = Math.abs(cx - SUN.x) < pathHalf(y) * 1.4;
    const band = SEA[Math.min(2, Math.max(0, Math.floor(depth * 3 + rand(-0.4, 0.4))))];
    const base = inPath
      ? mix(['sea', 1], ['skyGold', 1.2 + rand(0.6)])
      : rand() < 0.25
        ? band.rose
        : band.lilac;
    const tip = rand(-0.035, 0.035) * len;
    stroke({
      path: [
        [x, y - tip / 2],
        [x + len / 2, y + rand(-1, 1)],
        [x + len, y + tip / 2],
      ],
      brush: 'water',
      color: base,
      load: 0.8,
      pressure: rand(0.5, 0.8),
    });
  }
}
// a few ripples catching the sky, dragged lightly so they break on the weave
for (let i = 0; i < 36; i++) {
  const y = rand(HORIZON + 4, SHORE - 3);
  const x = rand(-20, W);
  if (Math.abs(x - SUN.x) < pathHalf(y) * 2) continue;
  stroke({
    path: [
      [x, y],
      [x + rand(30, 90), y + rand(-1.5, 1.5)],
    ],
    brush: { type: 'round', width: 2.5 },
    color: x > 700 ? 'skyLilac' : 'skyRose',
    load: 0.5,
    contact: 0.6,
    end: 'taper',
  });
}

// The water sets, so the glitter sits on top of it instead of melting in.
dry({ x: 0, y: HORIZON, w: W, h: SHORE - HORIZON + 4 });

// The glitter: short level dashes with dark water between, thickest at the path's
// center and scattering at its edges.
for (let i = 0; i < 120; i++) {
  const y = HORIZON + 2 + rand() ** 0.8 * (SHORE - HORIZON - 2);
  const spread = pathHalf(y) * (rand() + rand() - 1) * 1.6;
  const x = SUN.x + spread;
  const centre = 1 - Math.min(1, Math.abs(spread) / (pathHalf(y) * 1.6));
  const len = rand(3, 8) + centre * rand(4, 16);
  stroke({
    path: [
      [x - len / 2, y],
      [x + len / 2, y + rand(-0.5, 0.5)],
    ],
    brush: 'glint',
    color: centre > 0.55 ? mix(['white', 2], ['skyGlow', 1]) : rand() < 0.5 ? 'skyGlow' : 'skyGold',
    load: 0.9,
    pressure: 0.5 + centre * 0.4,
  });
}

// The surf line: a broken edge of foam where the last wave runs out on the sand,
// bright only under the sun and nearly lost in the violet elsewhere.
const surf = (x) => SHORE - 1 + noise(x / 90, 11) * 5 + noise(x / 23, 4) * 1.5;
for (let x = -10; x < W; x += rand(20, 70)) {
  const near = 1 - Math.min(1, Math.abs(x - SUN.x) / 420);
  if (rand() > 0.3 + near) continue;
  const len = rand(18, 60);
  stroke({
    path: [
      [x, surf(x)],
      [x + len / 2, surf(x + len / 2)],
      [x + len, surf(x + len)],
    ],
    brush: { type: 'round', width: 3 },
    color:
      near > 0.65
        ? mix(['white', 2], ['skyGlow', 1])
        : near > 0.3
          ? mix(['skyLilac', 1.5], ['sea', 0.3], ['white', 0.6])
          : mix(['skyLilac', 1.5], ['sea', 0.3], ['white', 0.15]),
    load: 0.4 + near * 0.5,
    contact: 0.55 + near * 0.45,
    pressure: 0.4 + near * 0.4,
    end: 'taper',
  });
}

dry({ x: 0, y: HORIZON - 60, w: W, h: SHORE - HORIZON + 66 });

/**
 * Passage 4: the sand, wet and dry.
 *
 * The wet sand is a dim mirror of the sky, so this passage looks at the sky it painted:
 * at() reads the dried color at the mirrored point above the horizon, and each upright
 * stroke carries that color, dulled with sand, down into the flats. Standing pools keep
 * the sky's full brightness; the sun's reflection runs down the middle as a column of
 * light. Level strokes of drier sand are then dragged across the uprights while both are
 * wet, the way reflections are painted on a real beach. Below, the dry sand comes
 * forward in broader strokes, lit along its ripples and falling into violet shade.
 */

const W = canvas.width;
const H = canvas.height;
const HORIZON = 332;
const SHORE = 372;
const SUN = { x: 432, y: 248 };

/** Where the wet sand gives way to dry (as in passage 1). */
function dryLine(x) {
  return 615 + 38 * noise(x / 170, 7.3) + Math.max(0, 300 - x) * 0.18;
}

/** Half-width of the sun's reflection on the sand at height y. */
const columnHalf = (y) => 30 + (y - SHORE) * 0.32;

/** The sky's dried color at the point mirrored in the wet sand. */
const mirrored = (x, y) => at(x, Math.max(2, 2 * HORIZON - y));

/**
 * Standing water: level pools, and a channel that winds in from the lower left. Each
 * pool is a flat ellipse; the channel is a chain of them along its course.
 */
const POOLS = [
  { x: 330, y: 448, rx: 270, ry: 16 },
  { x: 560, y: 402, rx: 200, ry: 8 },
  { x: 905, y: 496, rx: 160, ry: 11 },
  { x: 1090, y: 412, rx: 140, ry: 8 },
  { x: 620, y: 612, rx: 120, ry: 10 },
  { x: 1010, y: 580, rx: 150, ry: 9 },
];
for (let t = 0; t <= 1; t += 0.08) {
  POOLS.push({
    x: 300 - 250 * t + 30 * Math.sin(t * 5),
    y: 470 + 200 * t ** 1.2,
    rx: 40 + 60 * t,
    ry: 6 + 16 * t,
  });
}
/** How deep into a pool a point lies: 0 outside, up to 1 at its middle. */
function inPool(x, y) {
  let best = 0;
  for (const p of POOLS) {
    const d = ((x - p.x) / p.rx) ** 2 + ((y - p.y) / p.ry) ** 2;
    if (d < 1) best = Math.max(best, 1 - d);
  }
  return best;
}

brush('drag', { type: 'flat', width: 18, splay: 0.35 });
// stiff bristles, so the dry sand's broken colors sit side by side instead of churning together
brush('sandBroad', { type: 'filbert', width: 48, splay: 0.3, stiffness: 0.9 });
brush('sandMid', { type: 'filbert', width: 26, splay: 0.3, stiffness: 0.9 });

// Reflections: short upright strokes carrying the mirrored sky down into the wet sand,
// dull and dark on the sand, near full strength in the pools.
for (let y = SHORE + 2; y < 700; y += 9) {
  for (let x = rand(-6, 6); x < W; x += rand(8, 16)) {
    if (y > dryLine(x) + 6) continue;
    const pool = inPool(x, y);
    const column = Math.abs(x - SUN.x) < columnHalf(y) * rand(0.7, 1.1);
    const sky = mirrored(x, y);
    const far = (y - SHORE) / 280;
    let color;
    if (column)
      color =
        pool > 0
          ? mix(['white', 1], ['skyGlow', 2])
          : mix([sky, 2], ['skyGold', 1.5], ['sandWet', 0.8]);
    else if (pool > 0) color = mix([sky, 5], ['white', 0.4], ['sandWet', 0.4]);
    else color = mix([sky, 1], ['sandWet', 1.2], ['shade', far < 0.5 ? 1 : 1.6], ['sea', 0.15]);
    const len = rand(8, 26) + far * 12;
    stroke({
      path: [
        [x, y],
        [x + rand(-1, 1), y + len],
      ],
      brush: { type: 'flat', width: rand(9, 17), stiffness: 0.7 },
      color,
      load: 0.8,
      pressure: rand(0.5, 0.75),
    });
  }
}

// Bars of drier sand dragged level across the wet reflections, skirting the pools, so
// the flats break into bands the way a beach does when the tide is out.
for (let y = SHORE + 8; y < 700; y += rand(8, 14)) {
  for (let x = rand(-30, 0); x < W; x += rand(50, 120)) {
    const len = rand(60, 170) * (0.6 + (y - SHORE) / 330);
    if (y > dryLine(x) - 2 || inPool(x + len / 2, y) > 0 || rand() < 0.3) continue;
    const column = Math.abs(x + len / 2 - SUN.x) < columnHalf(y);
    stroke({
      path: [
        [x, y],
        [x + len / 2, y + rand(-1.5, 1.5)],
        [x + len, y + rand(-2, 2)],
      ],
      brush: 'drag',
      color: column
        ? mix(['skyGold', 2], ['sandDry', 1])
        : mix(
            ['sandWet', 1.5],
            ['sienna', 0.2],
            ['shade', 1],
            [rand() < 0.5 ? 'darkest' : 'alizarin', 0.08],
          ),
      load: rand(0.4, 0.65),
      pressure: rand(0.4, 0.65),
    });
  }
}

/**
 * The dry sand's piles: three bands from the lit, warm sand at the wet line to the
 * violet-brown shade at the bottom edge, each with a rose and a violet neighbor at much
 * the same value for broken color.
 */
const SAND_BASES = [
  [
    ['sandDry', 2.3],
    ['shade', 0.8],
    ['darkest', 0.22],
    ['skyGold', 0.6],
  ],
  [
    ['sandDry', 1.5],
    ['shade', 1.2],
    ['darkest', 0.96],
    ['skyGold', 0.25],
  ],
  [
    ['sandDry', 0.7],
    ['shade', 1.6],
    ['darkest', 2],
    ['skyGold', 0.07],
  ],
];
const SAND = SAND_BASES.map((base, b) => [
  mix(...base),
  mix(...base, ['alizarin', 0.15 + b * 0.05], ['skyRose', 0.5]),
  mix(...base, ['ultra', 0.12 + b * 0.05], ['alizarin', 0.12 + b * 0.03]),
]);
const RIPPLE_SHADOW = SAND.map(([, , violet], b) => mix([violet, 2], ['darkest', 0.3 + b * 0.1]));
const RIPPLE_LIGHT = SAND.map(([sand]) => mix(['skyPeach', 1], [sand, 1.5]));

/** The band of dry sand at a depth `near` (0 at the wet line, 1 at the bottom edge), its edges ragged. */
const sandBand = (near) => Math.min(2, Math.max(0, Math.floor(near * 3 + rand(-0.35, 0.35))));

// Dry sand: strokes that widen as the beach comes toward us, each tilted by the lie of
// the ground (a noise field), broken between warm sand and its rose and violet neighbors.
for (let y = 600; y < H + 20; ) {
  const near = Math.min(1, Math.max(0, (y - 620) / 280));
  for (let x = rand(-60, 0); x < W; x += rand(60, 120) * (0.7 + near)) {
    const len = rand(90, 200) * (0.7 + near);
    const cx = x + len / 2;
    if (y < dryLine(cx) - 4) continue;
    const a = noise(cx / 260, y / 140) * 0.22;
    const r = rand();
    stroke({
      path: [
        [x, y + rand(-3, 3)],
        [x + (len / 2) * Math.cos(a), y + (len / 2) * Math.sin(a) + rand(-4, 4)],
        [x + len * Math.cos(a), y + len * Math.sin(a) + rand(-4, 4)],
      ],
      brush: near > 0.45 ? 'sandBroad' : 'sandMid',
      color: SAND[sandBand(near)][r < 0.22 ? 1 : r < 0.42 ? 2 : 0],
      load: rand(0.8, 0.95),
    });
  }
  y += 11 + near * 22;
}

// Ripple marks: long low ridges across the dry sand, each lit along its crest where the
// sun still grazes it and shadowed just below.
for (let i = 0; i < 110; i++) {
  const y = rand(640, H - 6);
  const near = Math.min(1, (y - 620) / 280);
  const x = rand(-40, W);
  if (y < dryLine(x) + 12) continue;
  const len = rand(70, 160) * (0.6 + near);
  const bow = rand(-4, 4) * (0.5 + near);
  const crest = [
    [x, y],
    [x + len / 3, y - bow],
    [x + (2 * len) / 3, y + bow * 0.5],
    [x + len, y + rand(-3, 3)],
  ];
  stroke({
    path: crest.map(([px, py]) => [px + 2, py + 2 + near * 4]),
    brush: { type: 'round', width: 4 + near * 8 },
    color: RIPPLE_SHADOW[sandBand(near)],
    load: 0.55,
    pressure: 0.55,
    end: 'taper',
  });
  stroke({
    path: crest,
    brush: { type: 'round', width: 3 + near * 4 },
    color: near < 0.5 ? mix(['skyGold', 2], ['sandDry', 1]) : RIPPLE_LIGHT[sandBand(near)],
    load: 0.7,
    pressure: 0.45 + near * 0.3,
    end: 'taper',
  });
}

dry();

/**
 * Passage 5: the darks. Boats, the old posts, two walkers at the water's edge.
 *
 * With the sun behind them everything solid on the beach turns to a near-silhouette
 * with a thread of light along the edge that faces the sun. Their shadows come first,
 * glazed over the dried sand, falling toward us and away from the sun; then the shapes,
 * laid smoothly in a few strokes (piled-up dark paint catches the light on its ridges
 * and turns grey); then their reflections; then, once those have dried, the rims of light.
 */

const HORIZON = 332;
const SUN = { x: 432, y: 248 };

/** Where the wet sand gives way to dry (as in passage 1). */
function dryLine(x) {
  return 615 + 38 * noise(x / 170, 7.3) + Math.max(0, 300 - x) * 0.18;
}

/** Unit vector pointing from the sun's foot on the horizon to a point: the way a shadow falls there. */
function away(x, y) {
  const dx = x - SUN.x;
  const dy = y - HORIZON;
  const d = Math.hypot(dx, dy);
  return [dx / d, dy / d];
}

palette('boatDark', mix(['darkest', 3], ['sea', 0.5]));
palette('wood', mix(['darkest', 2], ['sienna', 1]));
palette('rim', mix(['skyGlow', 2], ['white', 1]));
const shadowGlaze = mix(['darkest', 2], ['ultra', 0.4], ['alizarin', 0.3]);
const strake = mix(['cadRed', 1], ['alizarin', 0.8], ['darkest', 1.2]);
const silhouette = mix(['darkest', 2], ['sea', 0.5]);
/** Darks go on a little lean and not too heavy, so they lie flat instead of ridging. */
const thin = { thinner: 0.12, load: 0.8 };

brush('hull', { type: 'flat', width: 13, stiffness: 0.8 });
brush('line', { type: 'round', width: 3 });
brush('hair', { type: 'round', width: 1.6 });
brush('glazer', { type: 'flat', width: 22, streak: 0.5 });

// The big boat: sheer (gunwale) and keel as curves along its length, u from stern to bow.
const boat = {
  x: (u) => 648 + 222 * u,
  sheer: (u) => 524 + 10 * Math.sin(Math.PI * u) - 20 * u ** 3,
  keel: (u) => (u < 0.8 ? 566 - 4 * u : 562.8 - ((u - 0.8) / 0.2) ** 2 * 50),
};
const along = (fn, u0, u1, step) => {
  const pts = [];
  for (let u = u0; u <= u1 + 1e-9; u += step) pts.push(fn(u));
  return pts;
};

// The far boat, the posts, and the walkers, as numbers.
const far = { x0: 946, x1: 1024, y: 432 };
const POSTS = [];
for (let i = 0; i < 7; i++) {
  const t = i / 6;
  POSTS.push({
    x: 150 + t * 175 + noise(i, 5) * 6,
    foot: 870 - (870 - 398) * t ** 0.8,
    tall: 120 * (1 - t) ** 1.4 + 10,
    w: 15 * (1 - t) + 3,
  });
}
const WALKERS = [
  { x: 522, foot: 389, tall: 36 },
  { x: 540, foot: 391, tall: 21 },
];

// Shadows, glazed over the dry sand: each falls toward us, away from the sun.
for (let u = 0; u <= 1; u += 0.06) {
  const x = boat.x(u);
  const y = boat.keel(Math.min(u, 0.8)) + 2;
  const [dx, dy] = away(x, y);
  const len = 58 + 30 * Math.sin(Math.PI * u);
  stroke({
    path: [
      [x, y],
      [x + dx * len, y + dy * len],
    ],
    brush: 'glazer',
    color: shadowGlaze,
    paint: 'glaze',
    load: 0.55,
    end: 'taper',
  });
}
for (const p of POSTS) {
  const [dx, dy] = away(p.x, p.foot);
  const len = p.tall * 0.9;
  stroke({
    path: [
      [p.x, p.foot],
      [p.x + dx * len, p.foot + dy * len],
    ],
    brush: { type: 'flat', width: p.w * 0.9 },
    color: shadowGlaze,
    paint: 'glaze',
    load: 0.6,
    end: 'taper',
  });
}

// The big boat's hull: rows that follow its curve, a red strake under the gunwale,
// dark below.
for (let v = 0.06; v < 1; v += 0.14) {
  stroke({
    path: along(
      (u) => [boat.x(u) + v * 8 * (1 - u), boat.sheer(u) + (boat.keel(u) - boat.sheer(u)) * v],
      0,
      0.97,
      0.1,
    ),
    brush: 'hull',
    color: v < 0.2 ? strake : 'boatDark',
    pressure: 0.7,
    ...thin,
  });
}
// the transom, square across the stern
stroke({
  path: [
    [649, 523],
    [652, 545],
    [656, 566],
  ],
  brush: 'line',
  color: 'boatDark',
  end: 'stop',
  ...thin,
});
// the mast, and a furled sail lashed along its boom
stroke({
  path: [
    [743, 531],
    [745, 470],
    [747, 404],
  ],
  brush: 'line',
  color: 'wood',
  end: 'taper',
  ...thin,
});
stroke({
  path: [
    [745, 500],
    [700, 507],
    [672, 512],
  ],
  brush: { type: 'round', width: 6 },
  color: mix(['boatDark', 1.5], ['skyRose', 0.5]),
  ...thin,
});
// the mooring line, sagging from the bow to its anchor in the sand
stroke({
  path: [
    [868, 509],
    [900, 548],
    [930, 584],
    [958, 598],
  ],
  brush: 'hair',
  color: 'wood',
  load: 0.8,
});

// The far boat, a sliver on the flats with a stub of mast.
for (let v = 0; v < 1; v += 0.34) {
  stroke({
    path: [
      [far.x0 + v * 3, far.y - 2 + v * 6],
      [(far.x0 + far.x1) / 2, far.y + 2 + v * 6],
      [far.x1 - v * 6, far.y - 6 + v * 5],
    ],
    brush: { type: 'filbert', width: 4 },
    color: 'boatDark',
    ...thin,
  });
}
stroke({
  path: [
    [982, 434],
    [983, 380],
  ],
  brush: 'hair',
  color: 'wood',
  load: 0.9,
  end: 'taper',
});

// The posts: weathered wood, a dark band of weed at the foot.
for (const p of POSTS) {
  for (let k = 0; k < 2; k++) {
    stroke({
      path: [
        [p.x + (k - 0.5) * p.w * 0.3, p.foot],
        [p.x + (k - 0.5) * p.w * 0.25 + rand(-1, 1), p.foot - p.tall * rand(0.94, 1)],
      ],
      brush: { type: 'flat', width: p.w * 0.75 },
      color: 'wood',
      end: 'stop',
      ...thin,
    });
  }
  stroke({
    path: [
      [p.x - p.w * 0.5, p.foot - p.tall * 0.12],
      [p.x + p.w * 0.5, p.foot - p.tall * 0.1],
    ],
    brush: { type: 'flat', width: Math.max(2, p.tall * 0.14) },
    color: mix(['darkest', 2], ['cadYellow', 0.3], ['ultra', 0.2]),
    ...thin,
  });
}

// The walkers: a figure and a child, hand in hand, stopped at the edge of the glitter.
for (const f of WALKERS) {
  const s = f.tall / 36;
  const legs = { type: 'round', width: 3 * s + 0.6 };
  stroke({
    path: [
      [f.x, f.foot - 17 * s],
      [f.x - 3 * s, f.foot],
    ],
    brush: legs,
    color: silhouette,
    end: 'stop',
    ...thin,
  });
  stroke({
    path: [
      [f.x, f.foot - 17 * s],
      [f.x + 3.5 * s, f.foot],
    ],
    brush: legs,
    color: silhouette,
    end: 'stop',
    ...thin,
  });
  stroke({
    path: [
      [f.x, f.foot - 16 * s],
      [f.x + 0.5, f.foot - 30 * s],
    ],
    brush: { type: 'round', width: 7 * s },
    color: silhouette,
    ...thin,
  });
  stroke({
    path: [[f.x + 0.5, f.foot - 33.5 * s]],
    brush: { type: 'round', width: 5.5 * s },
    color: silhouette,
    ...thin,
  });
}
stroke({
  path: [
    [525, 363],
    [531, 370],
    [538, 375],
  ],
  brush: { type: 'round', width: 1.8 },
  color: silhouette,
  ...thin,
});

// Reflections. The hull hangs upside down under its keel, as deep as the side is tall,
// broken into level dashes by the ripples: glazed, so they darken the sand and its
// shadow instead of covering them with a flat grey. Posts and figures drop broken
// uprights. Each fades as it goes down: a dark pile under the keel, a paler one below.
const REFLECTION = [mix(['boatDark', 2], ['sea', 0.5]), mix(['boatDark', 2], ['sea', 1.1])];
const reflected = (d) => REFLECTION[d + rand(-0.15, 0.15) < 0.5 ? 0 : 1];
const mirrorBottom = (u) => boat.keel(u) + (boat.keel(u) - boat.sheer(u)) * 0.85;
for (let y = 567; y < mirrorBottom(0.5); y += rand(4, 7)) {
  const d = (y - 566) / (mirrorBottom(0.5) - 566);
  if (rand() < 0.2 + d * 0.4) continue;
  // the stretch of hull whose mirror image reaches down to this row
  const span = along((u) => u, 0, 1, 0.02).filter((u) => y >= boat.keel(u) && y <= mirrorBottom(u));
  if (span.length < 2) continue;
  const x0 = boat.x(span[0]) + rand(0, 20) + d * 16;
  const x1 = boat.x(span[span.length - 1]) - rand(0, 20) - d * 16;
  stroke({
    path: [
      [x0, y],
      [(x0 + x1) / 2, y + rand(-1, 1)],
      [x1, y + rand(-1, 1)],
    ],
    brush: { type: 'flat', width: rand(3, 5) },
    color: reflected(d),
    paint: 'glaze',
    load: 0.8 - d * 0.4,
    end: 'taper',
  });
}
function reflectUpright(x, y, len, width, color) {
  for (let d = 0; d < len; ) {
    const seg = rand(4, 10);
    stroke({
      path: [
        [x + rand(-0.8, 0.8), y + d],
        [x + rand(-1.2, 1.2), y + d + seg],
      ],
      brush: { type: 'flat', width: width * rand(0.7, 1.1) },
      color,
      thinner: 0.35,
      load: 0.7 - (0.3 * d) / len,
      end: 'taper',
    });
    d += seg + rand(2, 6) * (1 + (2 * d) / len);
  }
}
reflectUpright(746, 574, 60, 2.2, mix(['wood', 2], ['sandWet', 1]));
for (let d = 1; d < 12; d += 3) {
  stroke({
    path: [
      [far.x0 + 6 + d, far.y + 4 + d],
      [far.x1 - 8 - d, far.y + 3 + d],
    ],
    brush: { type: 'flat', width: 2.5 },
    color: reflected(d / 12),
    ...thin,
  });
}
for (const p of POSTS)
  if (p.foot < dryLine(p.x) - 4)
    reflectUpright(p.x, p.foot + 1, p.tall * 0.7, p.w * 0.7, mix(['wood', 2], ['sandWet', 1]));
for (const f of WALKERS)
  reflectUpright(
    f.x,
    f.foot + 1,
    f.tall * 0.8,
    4 * (f.tall / 36) + 1,
    mix(['darkest', 2], ['skyGold', 0.6]),
  );

// The darks set, so the rims of light lie on them clean instead of turning grey.
dry();

// Rims: a thread of light on each edge that faces the sun, in fuller paint.
stroke({
  path: along((u) => [boat.x(u), boat.sheer(u) - 1], 0.08, 1, 0.08),
  brush: { type: 'round', width: 2.2 },
  color: 'rim',
  load: 0.9,
  pressure: 0.55,
  end: 'taper',
});
stroke({
  path: [
    [744, 468],
    [745, 438],
    [746, 408],
  ],
  brush: { type: 'round', width: 1 },
  color: 'rim',
  load: 0.5,
  pressure: 0.5,
  end: 'taper',
});
stroke({
  path: [
    [868, 506],
    [862, 524],
    [855, 545],
  ],
  brush: 'hair',
  color: mix(['rim', 1], ['skyPeach', 1]),
  load: 0.7,
  end: 'taper',
});
stroke({
  path: [
    [far.x0 + 2, far.y - 3.5],
    [(far.x0 + far.x1) / 2, far.y + 0.5],
    [far.x1, far.y - 8],
  ],
  brush: { type: 'round', width: 1.2 },
  color: 'rim',
  load: 0.8,
  end: 'taper',
});
for (const p of POSTS) {
  // the posts stand left of the sun, so their right sides catch it
  stroke({
    path: [
      [p.x + p.w * 0.38, p.foot - p.tall * 0.97],
      [p.x + p.w * 0.4, p.foot - p.tall * 0.35],
    ],
    brush: { type: 'round', width: Math.max(1, p.w * 0.16) },
    color: 'rim',
    load: 0.8,
    end: 'taper',
  });
}
for (const f of WALKERS) {
  const s = f.tall / 36;
  stroke({
    path: [
      [f.x - 2.6 * s, f.foot - 35 * s],
      [f.x - 3 * s, f.foot - 28 * s],
      [f.x - 3.4 * s, f.foot - 18 * s],
    ],
    brush: { type: 'round', width: 1 },
    color: 'rim',
    load: 0.8,
    end: 'taper',
  });
}

/**
 * Passage 6: the light, last and thickest.
 *
 * Over the dried painting: a cool glaze deepens the foreground so the eye goes past it
 * to the light; a worn brush breaks a little gold over the sand where the light grazes
 * it; a palette knife, lightly loaded so it skips, drags thin sparkle across the glitter
 * on the sea and down the sun's column on the wet sand; the sun itself goes on as a
 * knot of thick paint inside a ring of gold; and a few gulls cross the glow.
 */

const W = canvas.width;
const H = canvas.height;
const HORIZON = 332;
const SHORE = 372;
const SUN = { x: 432, y: 248 };

palette('sunCore', mix(['white', 5], ['cadYellow', 1]));

// The foreground glaze: a violet film from a soft brush, heaviest at the bottom corners.
// Its strength is set with thinner, not load: a lightly loaded brush would dry-brush
// and print the canvas weave.
const veil = mix(['ultra', 1], ['alizarin', 1], ['sienna', 0.4]);
for (let y = H - 10; y > 720; y -= 34) {
  const depth = (y - 720) / (H - 720);
  for (let x = -80; x < W; x += rand(140, 220)) {
    const len = rand(220, 320);
    const edge = Math.abs(x + len / 2 - W / 2) / (W / 2);
    if (rand() > depth * 0.6 + edge * 0.5) continue;
    stroke({
      path: [
        [x, y + rand(-8, 8)],
        [x + len / 2, y + rand(-10, 10)],
        [x + len, y + rand(-12, 12)],
      ],
      brush: { type: 'soft', width: 110, reservoir: 2 },
      color: veil,
      paint: 'glaze',
      load: 0.5,
      // two strengths: a heavier veil in the bottom corners, a light one elsewhere
      thinner: depth > 0.5 && edge > 0.5 ? 0.75 : 0.9,
    });
  }
}

// Sparkle: a thin, lightly loaded knife dragged level across the glitter, skipping on the weave.
for (let i = 0; i < 22; i++) {
  const y = rand(HORIZON + 3, SHORE - 4);
  const half = 20 + (y - HORIZON) * 0.7;
  const x = SUN.x + rand(-half, half);
  stroke({
    path: [
      [x - rand(6, 16), y],
      [x + rand(6, 16), y + rand(-0.6, 0.6)],
    ],
    brush: { type: 'knife', width: rand(2.5, 4) },
    color: rand() < 0.5 ? 'white' : 'sunCore',
    load: rand(0.25, 0.4),
  });
}
// and down the sun's column on the wet sand: flicks of a fine round brush, crowded near
// the sea and scattering as they come forward
for (let i = 0; i < 40; i++) {
  const y = SHORE + 6 + rand() ** 1.8 * 230;
  const half = 26 + (y - SHORE) * 0.3;
  const x = SUN.x + half * (rand() + rand() - 1);
  const len = rand(5, 16) * (1 - (y - SHORE) / 400);
  stroke({
    path: [
      [x - len / 2, y],
      [x + len / 2, y + rand(-0.8, 0.8)],
    ],
    brush: { type: 'round', width: rand(1.8, 3) },
    color: rand() < 0.5 ? 'sunCore' : 'skyGlow',
    load: 0.9,
    end: 'flick',
  });
}

// The sun: a knot of thick, nearly white paint pressed on with the knife, then a clean
// soft brush taken once around it, so its edge melts into the glow.
for (let i = 0; i < 13; i++) {
  const y = SUN.y + (i - 6) * 3.2;
  const half = Math.sqrt(Math.max(0, 1 - ((i - 6) / 6.6) ** 2)) * 21;
  stroke({
    path: [
      [SUN.x - half, y],
      [SUN.x + half, y + rand(-0.5, 0.5)],
    ],
    brush: { type: 'knife', width: 6 },
    color: Math.abs(i - 6) < 3 ? mix(['white', 8], ['cadYellow', 0.5]) : 'sunCore',
    load: 0.9,
  });
}
for (let a = 0; a < Math.PI * 2; a += Math.PI / 5) {
  const r = 22;
  stroke({
    path: [
      [SUN.x + Math.cos(a) * r, SUN.y + Math.sin(a) * r * 0.85],
      [SUN.x + Math.cos(a + 0.7) * r, SUN.y + Math.sin(a + 0.7) * r * 0.85],
    ],
    brush: { type: 'soft', width: 10 },
    pressure: 0.5,
  });
}

// Gulls: a bent stroke for each pair of wings, dark against the glow, smaller farther off.
const GULLS = [
  { x: 598, y: 142, s: 1, tilt: 0.1 },
  { x: 646, y: 168, s: 0.75, tilt: -0.15 },
  { x: 312, y: 108, s: 0.6, tilt: 0.2 },
  { x: 875, y: 205, s: 0.5, tilt: 0 },
  { x: 702, y: 120, s: 0.45, tilt: -0.05 },
];
for (const g of GULLS) {
  const span = 15 * g.s;
  const lift = 5 * g.s;
  const c = Math.cos(g.tilt);
  const s = Math.sin(g.tilt);
  const pt = (dx, dy) => [g.x + dx * c - dy * s, g.y + dx * s + dy * c];
  stroke({
    path: [
      pt(-span, -lift * 0.3),
      pt(-span * 0.45, -lift),
      pt(0, 0),
      pt(span * 0.45, -lift),
      pt(span, -lift * 0.2),
    ],
    brush: { type: 'round', width: 2.6 * g.s + 0.6 },
    color: mix(['darkest', 2], ['skyRose', 0.5]),
    load: 0.8,
    pressure: 0.55,
    end: 'taper',
  });
}
